style.css:
/* Peach Milk — Facebook */
:root {
  /* Đổi màu tại đây nếu muốn */
  --my-bg: #fff4ed;
  --my-card: #fffaf6;
  --my-accent: #e6a18f;
  --my-accent-light: #f8dcd2;
  --my-text: #624b43;
  --my-muted: #a58b80;
  --my-border: #f1ded5;
}

/* nền tổng thể */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* màu chữ */
body {
  --primary-text: var(--my-text) !important;
  --secondary-text: var(--my-muted) !important;
}

/* liên kết */
a {
  color: #c98275 !important;
}

/* nút bấm */
button,
[role="button"] {
  border-radius: 14px !important;
}

/* màu khi chọn văn bản */
::selection {
  background: #f5c9bb !important;
  color: #624b43 !important;
}

/* thanh cuộn */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: #e9b9a9 !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: #fff4ed !important;
}
